import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Welcome to VERA","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),s={name:"guide/index.md"};function n(i,e,l,h,d,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="welcome-to-vera" tabindex="-1">Welcome to VERA <a class="header-anchor" href="#welcome-to-vera" aria-label="Permalink to &quot;Welcome to VERA&quot;">​</a></h1><p>VERA is your team&#39;s time management assistant, built into Slack. You talk to them the same way you&#39;d message a colleague — in plain language, whenever it suits you.</p><p>No timesheets to fill. No dashboards to log into. No end-of-week scramble to remember what you did on Tuesday.</p><hr><h2 id="what-vera-does" tabindex="-1">What VERA does <a class="header-anchor" href="#what-vera-does" aria-label="Permalink to &quot;What VERA does&quot;">​</a></h2><p><strong>For team members:</strong> Log your hours as you work. Tell VERA what you worked on, which project, and how long. They&#39;ll record it, link it to the right place, and confirm back to you.</p><p><strong>For managers:</strong> Each morning you receive a summary of where your projects stand — burn rates, hours logged, any time-off requests waiting for approval. You also see alerts when a project is running ahead of schedule or close to its budget.</p><p><strong>For owners:</strong> Everything managers see, plus financial figures. Revenue recognised, cost, margin — all live, in Slack, without opening a spreadsheet.</p><hr><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p><strong>I need to log my hours</strong> → <a href="./logging-time.html">Logging time</a></p><p><strong>I need to request time off</strong> → <a href="./time-off.html">Time off</a></p><p><strong>I want to understand my morning message</strong> → <a href="./morning-briefing.html">The morning briefing</a></p><p><strong>I&#39;m not sure what I can see or do</strong> → <a href="./roles.html">Your role in VERA</a></p><p><strong>I need to understand projects and tasks</strong> → <a href="./projects.html">Projects and tasks</a></p><hr><h2 id="how-vera-works" tabindex="-1">How VERA works <a class="header-anchor" href="#how-vera-works" aria-label="Permalink to &quot;How VERA works&quot;">​</a></h2><p>You DM VERA in Slack. They read what you&#39;ve written, work out what you need, and either do it or ask a clarifying question.</p><p>VERA doesn&#39;t require specific commands or keywords. Say it however feels natural:</p><blockquote><p>&quot;Log 3 hours on the Adidas project, design work&quot;</p></blockquote><blockquote><p>&quot;Can you add 4h to Nike, video editing, for yesterday?&quot;</p></blockquote><blockquote><p>&quot;How much have I logged this week?&quot;</p></blockquote><blockquote><p>&quot;I need Friday off&quot;</p></blockquote><blockquote><p>&quot;Show me all work I need to do&quot;</p></blockquote><p>If something is ambiguous — two projects with similar names, or a task that could go a few ways — VERA will ask before doing anything.</p>',25)])])}const m=o(s,[["render",n]]);export{g as __pageData,m as default};
